// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 seedAmount, address recipientAddr) public {
        uint256 amount = bound(seedAmount, 1, 1 ether);

        PayableRecipient recipient = new PayableRecipient();

        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = address(recipient).balance;

        vm.prank(address(this));
        c.withdrawAll(address(recipient));

        assertTrue(address(recipient).balance == beforeRecipient + beforeC);
    }
}

contract PayableRecipient {
    receive() external payable {}
}
